create or replace function public.get_operations_copilot_evidence_status() returns table(job_id uuid,evidence_count bigint,last_evidence_at timestamptz,last_checkpoint integer) language plpgsql security definer set search_path=public set row_security=off as $$ begin if public.current_role()<>'platform_admin' then raise exception 'PLATFORM_ADMIN_REQUIRED'; end if; return query select m.job_id,count(*)::bigint,max(coalesce(m.captured_at,m.created_at)),max(m.checkpoint_index) from public.mission_evidence_media m join public.marketplace_jobs j on j.id=m.job_id where j.status::text in ('accepted','assigned','active') group by m.job_id; end $$; revoke all on function public.get_operations_copilot_evidence_status() from public,anon; grant execute on function public.get_operations_copilot_evidence_status() to authenticated;
